import sqlite3,re,json
c=sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
tabs=[r[0] for r in c.execute("select name from sqlite_master where type='table' and name!='sqlite_sequence' order by 1")]
ddl=dict(c.execute("select name,sql from sqlite_master where type='table'"))
js=[];blobs=[];longtxt=[];jsd=[]
for t in tabs:
    for cid,name,typ,nn,dflt,pk in c.execute(f'pragma table_info("{t}")'):
        q=f'"{name}"'
        try:
            nb=c.execute(f'select count(*) from "{t}" where typeof({q})="blob"').fetchone()[0]
            if nb: blobs.append((t,name,nb))
            vals=c.execute(f'select {q} from "{t}" where typeof({q})="text" and ({q} like "[%" or {q} like "{{%") limit 200').fetchall()
            ok=0
            for (v,) in vals:
                try: json.loads(v); ok+=1
                except: pass
            if ok: js.append((t,name,ok))
            m=c.execute(f'select max(length({q})) from "{t}" where typeof({q})="text"').fetchone()[0]
            if m and m>1500: longtxt.append((t,name,m))
        except Exception as e: print('err',t,name,e)
    # json named in DDL
    for m in re.finditer(r'json_valid\((\w+)\)',ddl[t] or '',re.I): jsd.append((t,m.group(1)))
print('JSON-valued TEXT (by sampling):',js)
print('json_valid CHECK:',jsd)
print('BLOB values:',blobs)
print('LONG TEXT cols (>1500 chars):',sorted(longtxt,key=lambda x:-x[2])[:20])
# admitted_ref_ids
for t in tabs:
    for r in c.execute(f'pragma table_info("{t}")'):
        if re.search(r'admitted_ref|_ids$|_refs$|_json$|_sources$|governing_refs|supporting',r[1]): print('NAMED-LIST COL',t,r[1],r[2])
